/**
 * Paths of the static assets the app ships (the Conduit mark), resolved
 * from the compiled module's location. The build copies them from
 * `apps/desktop/assets/icon/` (generated by `render.mjs` there) into
 * `dist/assets/icon/` (see `scripts/copy-renderer.mjs`). Electron-free.
 */

import * as path from "node:path";
import { fileURLToPath } from "node:url";

const ICON_DIR = path.join(path.dirname(fileURLToPath(import.meta.url)), "assets", "icon");

/** The 256px app tile: the icon of every Conduit window. */
export const APP_ICON_PATH = path.join(ICON_DIR, "conduit-app-256.png");

/** The opaque 1024px app tile set as the Discord bot's avatar when it has none. */
export const BOT_AVATAR_PATH = path.join(ICON_DIR, "conduit-bot-avatar.png");

/**
 * The shipped files, relative to `apps/desktop/assets/icon/`. The build copies
 * each into `dist/assets/icon/` under its base name.
 */
export const SHIPPED_ICON_FILES = ["png/conduit-app-256.png", "discord/conduit-bot-avatar.png"];
